"""HTML templates for the DJI Phone Gateway dashboard."""

LOGIN_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Sign in · DJI Phone Gateway</title><meta name="theme-color" content="#f7f7f8"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="icon" type="image/svg+xml" href="/icon.svg"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png"><style>
:root{color-scheme:light;--bg:#f7f7f8;--surface:#fff;--text:#111;--secondary:#6e6e73;--line:rgba(17,17,17,.10);--blue:#007aff;--red:#ff3b30}*{box-sizing:border-box}html,body{min-height:100%;background:var(--bg)}body{margin:0;color:var(--text);font:16px/1.4 "Helvetica Neue",Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}.login-shell{min-height:100dvh;display:grid;place-items:center;padding:max(24px,env(safe-area-inset-top)) 20px max(24px,env(safe-area-inset-bottom))}.login-card{width:min(100%,430px);overflow:hidden;border:1px solid var(--line);border-radius:30px;background:var(--surface)}.login-identity{padding:34px 32px 28px;border-bottom:1px solid var(--line)}.app-mark{display:grid;place-items:center;width:68px;height:68px;margin-bottom:30px;border-radius:18px;background:var(--text);color:#fff;font-size:1.35rem;font-weight:700;letter-spacing:-.05em}.login-identity h1{margin:0;font-size:2.35rem;line-height:1;letter-spacing:-.055em}.login-identity p{margin:10px 0 0;color:var(--secondary)}.login-form{padding:10px 32px 34px}.error{margin:14px 0 4px;padding:12px 14px;border-radius:12px;background:rgba(255,59,48,.09);color:#b42318;font-size:.9rem;font-weight:600}label{display:block;margin:18px 0 7px;color:var(--secondary);font-size:.78rem;font-weight:600}input[type=text],input[type=password]{width:100%;height:50px;border:1px solid var(--line);border-radius:12px;background:var(--bg);color:var(--text);padding:0 14px;font:inherit;outline:0;transition:border-color .18s ease,box-shadow .18s ease}input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(0,122,255,.14)}.remember{display:flex;align-items:center;gap:10px;margin:19px 0 22px;color:var(--text);font-size:.9rem}.remember input{width:18px;height:18px;accent-color:var(--blue)}button{width:100%;min-height:50px;border:0;border-radius:13px;background:var(--blue);color:#fff;font:600 1rem/1.2 "Helvetica Neue",Helvetica,Arial,sans-serif;cursor:pointer;transition:filter .18s ease,transform .18s ease}button:hover{filter:brightness(.94)}button:active{transform:scale(.985)}@media(max-width:480px){.login-shell{padding-left:14px;padding-right:14px}.login-card{border-radius:25px}.login-identity,.login-form{padding-left:24px;padding-right:24px}}
</style></head><body><main class="login-shell"><section class="login-card"><div class="login-identity"><div class="app-mark" aria-hidden="true">4G</div><h1>Welcome back</h1><p>Sign in to your phone gateway.</p></div><form class="login-form" method="post" action="/login">@@ERROR@@<input type="hidden" name="csrf" value="@@CSRF@@"><input type="hidden" name="next" value="@@NEXT@@"><label for="username">Username</label><input id="username" name="username" type="text" autocomplete="username" required autofocus><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><label class="remember"><input name="remember" type="checkbox" value="yes" checked>Keep me signed in for 30 days</label><button type="submit">Sign in</button></form></section></main></body></html>"""


